import { Redirect } from 'expo-router';

import { ErrorState, LoadingState } from '@/components/ui/States';
import { useGameStore } from '@/store/useGameStore';

export default function EntryScreen() {
  const status = useGameStore((state) => state.bootstrapStatus);
  const onboardingComplete = useGameStore((state) => state.onboardingComplete);
  const retry = useGameStore((state) => state.retryBootstrap);
  if (status === 'error') return <ErrorState messageKey="errors.database" onRetry={() => void retry()} />;
  if (status !== 'ready') return <LoadingState />;
  return <Redirect href={onboardingComplete ? '/(tabs)' : '/onboarding'} />;
}

import { Stack } from 'expo-router';
import { StatusBar } from 'expo-status-bar';
import { useEffect } from 'react';
import { I18nextProvider } from 'react-i18next';
import { SafeAreaProvider } from 'react-native-safe-area-context';

import i18n from '@/i18n';
import { useGameStore } from '@/store/useGameStore';
import { colors } from '@/theme/tokens';

function AppNavigator() {
  const bootstrap = useGameStore((state) => state.bootstrap);
  const language = useGameStore((state) => state.profile.language);

  useEffect(() => { void bootstrap(); }, [bootstrap]);
  useEffect(() => { void i18n.changeLanguage(language); }, [language]);

  return (
    <>
      <StatusBar style="light" />
      <Stack screenOptions={{ headerShown: false, contentStyle: { backgroundColor: colors.canvas }, animation: 'fade' }}>
        <Stack.Screen name="index" />
        <Stack.Screen name="onboarding" />
        <Stack.Screen name="(tabs)" />
        <Stack.Screen name="journey/[id]" options={{ animation: 'slide_from_right' }} />
        <Stack.Screen name="achievements" options={{ animation: 'slide_from_right' }} />
      </Stack>
    </>
  );
}

export default function RootLayout() {
  return <SafeAreaProvider><I18nextProvider i18n={i18n}><AppNavigator /></I18nextProvider></SafeAreaProvider>;
}

import { Feather } from '@expo/vector-icons';
import { Tabs } from 'expo-router';
import { useTranslation } from 'react-i18next';

import { colors } from '@/theme/tokens';

export default function TabLayout() {
  const { t } = useTranslation();
  return (
    <Tabs screenOptions={{
      headerShown: false, tabBarActiveTintColor: colors.goldSoft, tabBarInactiveTintColor: colors.muted,
      tabBarStyle: { backgroundColor: colors.surface, borderTopColor: colors.border, height: 78, paddingTop: 8, paddingBottom: 12 },
      tabBarLabelStyle: { fontSize: 11, fontWeight: '600' }, sceneStyle: { backgroundColor: colors.canvas },
    }}>
      <Tabs.Screen name="index" options={{ title: t('tabs.journey'), tabBarIcon: ({ color, size }) => <Feather name="compass" color={color} size={size} /> }} />
      <Tabs.Screen name="explore" options={{ title: t('tabs.explore'), tabBarIcon: ({ color, size }) => <Feather name="map" color={color} size={size} /> }} />
      <Tabs.Screen name="quests" options={{ title: t('tabs.quests'), tabBarIcon: ({ color, size }) => <Feather name="flag" color={color} size={size} /> }} />
      <Tabs.Screen name="profile" options={{ title: t('tabs.profile'), tabBarIcon: ({ color, size }) => <Feather name="user" color={color} size={size} /> }} />
    </Tabs>
  );
}

